SELECT n.*, u.nickname as from_nickname, u.avatar as from_avatar
FROM notification n
LEFT JOIN user u ON n.from_user_id = u.id
WHERE n.user_id = #{userId}
ORDER BY n.create_time DESC
LIMIT #{offset}, #{limit}

